using UnityEngine;

namespace CatBattleground
{
    /// <summary>
    /// Cinematic atmosphere for the arena, made at runtime (no scene rebuild needed): a light haze (linear fog that starts
    /// closer than the arena bake sets it), a longer camera far plane, and a cloudy sky of big soft billboard clouds
    /// (Resources/FX/Cloud, generated by FxAssets) above the drop plane's altitude plus a hazy ring of clouds on the horizon.
    /// The cloud layer turns very slowly around the island. Only in scenes with an "Arena"; nothing in batch mode (server).
    /// </summary>
    public class SceneAtmosphere : MonoBehaviour
    {
        // wind (foliage shader _CB_Wind, falling leaves, butterflies drift)
        public static Vector2 WindDir = new Vector2(0.8f, 0.6f).normalized;   // world x, z
        public static float WindStrength = 0.05f;   // metres of sway at a grass tip / leaf with weight 1
        public static float WindSpeed = 1.7f;

        // haze
        public static float FogStart = 60f, FogEnd = 420f;
        public static Color FogColor = new Color(0.74f, 0.83f, 0.9f);
        const float FarClip = 3200f;        // 2026-11-01: reaches the edge of the endless sea disc (fog hides everything past 420 m)
        const float SeaRadius = 3000f;

        // clouds
        const int HighClouds = 34, HorizonClouds = 22;
        const float SpinDegPerSec = 0.12f;

        Camera cam;
        Transform seaDisc;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void Boot()
        {
            if (Application.isBatchMode || GameObject.Find("Arena") == null || FindAnyObjectByType<SceneAtmosphere>() != null) return;
            new GameObject("Atmosphere (runtime)").AddComponent<SceneAtmosphere>();
        }

        void Start()
        {
            RenderSettings.fog = true;
            RenderSettings.fogMode = FogMode.Linear;
            RenderSettings.fogColor = FogColor;
            RenderSettings.fogStartDistance = FogStart;
            RenderSettings.fogEndDistance = FogEnd;
            Shader.SetGlobalVector("_CB_Wind", new Vector4(WindDir.x, WindDir.y, WindStrength, WindSpeed));
            BuildEndlessSea();
            if (!GameInput.TouchMode) gameObject.AddComponent<AmbientLife>();   // phones: skip the leaves / butterflies

            var mat = Resources.Load<Material>("FX/Cloud");
            if (mat == null) { Debug.LogWarning("[Atmosphere] Resources/FX/Cloud.mat missing (menu: CatBattleground > Rebuild Weapon FX Assets)"); return; }
            BuildClouds(mat);
        }

        /// <summary>
        /// The arena's sea is a 600 m square that showed its edges from the drop plane (user, 2026-11-01). It is replaced at runtime by
        /// a 3 km disc with the same material that follows the camera, and the procedural sky's ground colour (what shows below the
        /// horizon) becomes the fog colour, so the far sea melts into the horizon. No scene rebuild needed.
        /// </summary>
        void BuildEndlessSea()
        {
            var old = GameObject.Find("Arena/Sea");
            var oldRenderer = old != null ? old.GetComponent<Renderer>() : null;
            Material mat = oldRenderer != null ? oldRenderer.sharedMaterial : null;
            float y = old != null ? old.transform.position.y : -0.95f;
            if (mat == null)
            {
                var shader = Shader.Find("Universal Render Pipeline/Lit");
                if (shader == null) return;
                mat = new Material(shader); mat.SetColor("_BaseColor", new Color(0.22f, 0.58f, 0.74f)); mat.SetFloat("_Smoothness", 0.7f);
            }
            const int seg = 96;
            var v = new Vector3[seg + 1]; var nrm = new Vector3[seg + 1]; var tri = new int[seg * 3];
            v[0] = Vector3.zero; nrm[0] = Vector3.up;
            for (int i = 0; i < seg; i++)
            {
                float a = i * Mathf.PI * 2f / seg;
                v[i + 1] = new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a)) * SeaRadius;
                nrm[i + 1] = Vector3.up;
                tri[i * 3] = 0; tri[i * 3 + 1] = (i + 1) % seg + 1; tri[i * 3 + 2] = i + 1;
            }
            var mesh = new Mesh { name = "EndlessSea", vertices = v, normals = nrm, triangles = tri };
            mesh.bounds = new Bounds(Vector3.zero, new Vector3(SeaRadius * 2f, 1f, SeaRadius * 2f));
            var go = new GameObject("Sea (endless)");
            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            var mr = go.AddComponent<MeshRenderer>();
            mr.sharedMaterial = mat;
            mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            go.transform.position = new Vector3(0f, y, 0f);
            seaDisc = go.transform;
            if (oldRenderer != null) oldRenderer.enabled = false;   // the square would z-fight with the disc

            if (RenderSettings.skybox != null && RenderSettings.skybox.HasProperty("_GroundColor"))
            {
                var sky = new Material(RenderSettings.skybox);   // a copy: the asset on disk stays as it is
                sky.SetColor("_GroundColor", FogColor);
                RenderSettings.skybox = sky;
            }
        }

        void LateUpdate()
        {
            // the camera can be replaced (spectate, scene changes): keep its far plane long enough for the horizon clouds
            if (cam == null) cam = Camera.main;
            if (cam != null && cam.farClipPlane < FarClip) cam.farClipPlane = FarClip;
            if (seaDisc != null && cam != null)   // the disc rides under the camera, so its rim is never in view
            {
                var c = cam.transform.position;
                seaDisc.position = new Vector3(c.x, seaDisc.position.y, c.z);
            }
            transform.Rotate(0f, SpinDegPerSec * Time.deltaTime, 0f, Space.World);
        }

        void BuildClouds(Material mat)
        {
            var go = new GameObject("Clouds");
            go.transform.SetParent(transform, false);
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);

            var main = ps.main;
            main.loop = false;
            main.playOnAwake = false;
            main.duration = 1f;
            main.startLifetime = 100000f;
            main.startSpeed = 0f;
            main.maxParticles = HighClouds + HorizonClouds;
            main.simulationSpace = ParticleSystemSimulationSpace.Local;   // the layer turns with this transform
            main.scalingMode = ParticleSystemScalingMode.Hierarchy;
            var emission = ps.emission; emission.enabled = false;
            var shape = ps.shape; shape.enabled = false;

            var r = go.GetComponent<ParticleSystemRenderer>();
            r.sharedMaterial = mat;
            r.renderMode = ParticleSystemRenderMode.Billboard;
            r.alignment = ParticleSystemRenderSpace.View;
            r.sortMode = ParticleSystemSortMode.Distance;
            r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            r.receiveShadows = false;
            r.maxParticleSize = 10f;    // clouds can fill the screen when the camera flies close
            r.minParticleSize = 0f;

            var rnd = new System.Random(4663);
            float F(float a, float b) => a + (float)rnd.NextDouble() * (b - a);
            var ep = new ParticleSystem.EmitParams();

            // high layer: above the drop plane (120 m) so the jump view looks over a cloudy sky without being blocked
            for (int i = 0; i < HighClouds; i++)
            {
                float ang = F(0f, Mathf.PI * 2f), rad = Mathf.Sqrt(F(0.05f, 1f)) * 320f;
                ep.position = new Vector3(Mathf.Cos(ang) * rad, F(150f, 240f), Mathf.Sin(ang) * rad);
                ep.startSize = F(60f, 140f);
                ep.rotation = 0f;   // flat bottoms stay flat
                float shade = F(0.88f, 1f);
                ep.startColor = new Color(shade, shade, Mathf.Min(1f, shade * 1.03f), F(0.55f, 0.85f));
                ep.startLifetime = 100000f;
                ep.velocity = Vector3.zero;
                ps.Emit(ep, 1);
            }
            // horizon ring: low, far and hazy (fog blends them into the sky) for the cinematic skyline
            for (int i = 0; i < HorizonClouds; i++)
            {
                float ang = (i + F(-0.3f, 0.3f)) / HorizonClouds * Mathf.PI * 2f, rad = F(300f, 400f);
                ep.position = new Vector3(Mathf.Cos(ang) * rad, F(55f, 110f), Mathf.Sin(ang) * rad);
                ep.startSize = F(90f, 170f);
                ep.rotation = 0f;
                float shade = F(0.9f, 1f);
                ep.startColor = new Color(shade, shade, shade, F(0.5f, 0.75f));
                ep.startLifetime = 100000f;
                ep.velocity = Vector3.zero;
                ps.Emit(ep, 1);
            }
            ps.Pause();   // no simulation cost: the particles never move on their own
        }
    }
}
